            groups[-1].append(r)

    if len(groups) == 2 and len(groups[0]) == len(groups[1]):
        upper, lower = groups

        # Find the horizontal translation that best aligns the two patterns.
        best_shift, best_score = 0, -1
        for shift in range(-w + 1, w):
            score = 0
            for ru, rl in zip(upper, lower):
                for cu in range(w):
                    cl = cu - shift
                    if 0 <= cl < w and grid[ru][cu] != bg and grid[rl][cl] != bg:
                        score += 1
            if score > best_score or (score == best_score and abs(shift) < abs(best_shift)):
                best_shift, best_score = shift, score

        # Mark the pattern difference on the group with fewer foreground cells.
        for ru, rl in zip(upper, lower):
            upper_set = {c for c in range(w) if grid[ru][c] != bg}
            lower_aligned = {
                c + best_shift for c in range(w)
                if 0 <= c + best_shift < w and grid[rl][c] != bg
            }
            upper_only = upper_set - lower_aligned
            lower_only = lower_aligned - upper_set

            if len(lower_only) >= len(upper_only):
